import React, { useEffect, useRef, useState } from 'react';
import './Product.css';
import Img1 from "../assets/images/img1.jpeg";
import Img2 from "../assets/images/img2.jpeg";
import Img3 from "../assets/images/img3.jpeg";
import Img4 from "../assets/images/img4.jpeg";
import Img5 from "../assets/images/img5.jpeg";
import Img6 from "../assets/images/img6.jpeg";

const Products = () => {
  const sectionRef = useRef(null);
  const [isVisible, setIsVisible] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  // Sample placeholder image list - update or map dynamically if needed
  const defaultImages = [Img1, Img2, Img3, Img4, Img5, Img6];

  const categories = [
    {
      name: "MASTER SMART HOME",
      products: [
        { name: "ILLUMINATION", description: "Smart lighting control (Wi-Fi)", image: Img1 },
        { name: "SHADING SYSTEMS", description: "Smart awnings and shutters (Wi-Fi)", image: Img2 },
        { name: "APPLIANCES CONTROL", description: "Smart appliance control (Wi-Fi)", image: Img3 },
        { name: "HEATING / COOLING", description: "Smart heating and cooling (Wi-Fi)", image: Img4 },
        { name: "VISUALIZATION", description: "Smart control and management (Wi-Fi)", image: Img5 }
      ]
    },
    {
      name: "LED CONTROLLERS",
      products: [
        { name: "LD-250W", description: "LED Controller (Button & 1-10V)", image: Img6 },
        { name: "LD-250W-RF", description: "LED Controller (Button & RF)", image: Img1 },
        { name: "LD-250W-BST", description: "Booster Amplifier (1 Channel)", image: Img2 },
        { name: "LD-RGB-BST", description: "Booster Amplifier (RGB)", image: Img3 },
        { name: "LD-RGB", description: "LED Controller (Button & 1-10V) 3 Channel RGB", image: Img4 }
      ]
    },
    {
      name: "WALL – MOUNTING DIMMER",
      products: [
        { name: "DM-400L/N", description: "Wall Mounting Dimmer Multi 1000W", image: Img5 },
        { name: "DM-1000W", description: "Allerretour", image: Img6 }
      ]
    },
    {
      name: "FLUSH – MOUNTING DIMMER",
      products: [
        { name: "DM-400B", description: "Flush Mounted Dimmer 400W (Control with Button)", image: Img1 },
        { name: "DM-400B-RF", description: "Flush Mounted Dimmer 400W (Button & RF)", image: Img2 }
      ]
    },
    {
      name: "RAIL – MOUNTING DIGITAL DIMMER",
      products: [
        { name: "DM-300/b", description: "Rail Mounting Dimmer 300W LED (Remote Control)", image: Img3 },
        { name: "DM-DGL/b", description: "Rail Mounting Digital Dimmer 1000W", image: Img4 }
      ]
    },
    {
      name: "SURFACE – MOUNTING DIMMER",
      products: [
        { name: "DM-2500W", description: "Dimmer Professional Multi-LED 2500W", image: Img5 },
        { name: "DM-2500", description: "Dimmer Professional Multi-LED 2500W", image: Img6 },
        { name: "DM-PRO 1-10V", description: "Dimmer Professional 1-10V", image: Img1 }
      ]
    },
    {
      name: "DMX LED Controllers",
      products: [
        { name: "LD-250W-DMX", description: "LED Controller DMX-512 (1 Channel)", image: Img2 },
        { name: "LD-RGB-DMX", description: "LED Controller DMX-512 (3 Channel) RGB", image: Img3 }
      ]
    },
    {
      name: "MULTIDIMMER 8 CHANNEL",
      products: [
        { name: "DM-LCD", description: "Remote Control Unit", image: Img4 },
        { name: "DM-8CHL", description: "8 Channel Control Unit", image: Img5 },
        { name: "DM-CHL", description: "Terminal Power Units 1kW", image: Img6 },
        { name: "DM-CHL-1-10V", description: "Terminal Units with 1-10V Output", image: Img1 }
      ]
    },
    {
      name: "BIOMASS CONTROLLER",
      products: [
        { name: "PWC-2500", description: "Pellet Controller (New)", image: Img2 },
        { name: "PWC-1000", description: "Pellet Controller", image: Img3 }
      ]
    },
    {
      name: "TIMERS",
      products: [
        { name: "KL-4000", description: "Staircase Timer Switch", image: Img4 }
      ]
    },
    {
      name: "INDICATING LAMPS",
      products: [
        { name: "ML-100 & SL-100", description: "Indicating Lamp (Single)", image: Img5 },
        { name: "TL-300", description: "Indicating Lamp (Triple)", image: Img6 }
      ]
    },
    {
      name: "SECURITY SYSTEMS",
      products: [
        { name: "CM-DOOR", description: "Security Doors with Electric Locks", image: Img1 }
      ]
    }
  ];

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.3 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <>
      <section
        ref={sectionRef}
        className={`products-section fade-in-section ${isVisible ? 'visible' : ''}`}
      >
        <div className="container">
          <h2 className="products-title">Our Products</h2>

          {categories.map((category, catIndex) => (
            <div key={catIndex} className="category-section">
              <h3 className="category-title">{category.name}</h3>
              <div className="products-grid">
                {category.products.map((product, index) => (
                  <div
                    key={`${catIndex}-${index}`}
                    className="product-card"
                    style={{ transitionDelay: `${index * 100}ms` }}
                    onClick={() => setSelectedProduct(product)}
                  >
                    <img src={product.image} alt={product.name} />
                    <h4>{product.name}</h4>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </section>

      {selectedProduct && (
        <div className="product-modal">
          <div className="modal-content">
            <button className="close-button" onClick={() => setSelectedProduct(null)}>×</button>
            <img src={selectedProduct.image} alt={selectedProduct.name} />
            <h2>{selectedProduct.name}</h2>
            <p>{selectedProduct.description}</p>
          </div>
        </div>
      )}
    </>
  );
};

export default Products;
